#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#include <iomanip>
int main(){try{auto robot=hipRollModel();need(robot.mechanics.joints.at(5).axis0.y==-1.f,"unexpected axis");robot.mechanics.joints.at(5).axis0.y=1.f;const auto&m=robot.mechanics;need(m.defaultQ.size()==41 && m.defaultV.size()==40 && m.bodies.size()==35,"model size mismatch");need(m.bodyNames.at(11)=="crow_left_foot" && m.bodyNames.at(15)=="crow_right_foot","foot mapping mismatch");need(m.dofNames.at(38)=="crow_left_hip_roll" && m.dofNames.at(39)=="crow_right_hip_roll" && m.dofs.at(38).qIndex==39 && m.dofs.at(39).qIndex==40,"hip mapping mismatch");std::cout<<std::setprecision(17);int lane,step;while(std::cin>>lane>>step){std::vector<double> q(m.defaultQ.size()),v(m.defaultV.size());for(auto&x:q)need(bool(std::cin>>x),"missing q");for(auto&x:v)need(bool(std::cin>>x),"missing v");for(int variant=0;variant<5;variant++){auto qd=q;if(variant==1)qd[39]+=.01;if(variant==2)qd[39]-=.01;if(variant==3)qd[40]+=.01;if(variant==4)qd[40]-=.01;std::vector<ArticulatedBodyKinematics> k(m.bodies.size());need(computeArticulatedBodyKinematics(m,0,qd,v,k).succeeded(),"FK failed");double mass=0,c[3]={};for(unsigned i=0;i<k.size();++i){double w=m.bodies[i].massAndInverseMass.x;mass+=w;for(int j=0;j<3;++j)c[j]+=w*k[i].centerOfMassPosition[j];}std::cout<<lane<<" "<<step<<" "<<variant;for(double x:c)std::cout<<" "<<x/mass;for(int body:{11,15})for(int j=0;j<3;++j)std::cout<<" "<<k[body].centerOfMassPosition[j];std::cout<<"\n";}}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
